import fs from 'node:fs'
import path from 'node:path'
import {
  GATE_ENVIRONMENT_EVIDENCE_MATRIX,
  GATE_EVIDENCE_MATRIX
} from './certification-rules.mjs'

// These are generated by the later commands in coverage's && chain. The
// critical-coverage manifest is source input and must never be invalidated.
const coverageSubresults = [
  'certification/critical-coverage.json',
  'certification/mutation-guard.json'
]

export function invalidateGeneratedGateResults({ root, gateId }) {
  const matrix = Object.hasOwn(GATE_EVIDENCE_MATRIX, gateId)
    ? GATE_EVIDENCE_MATRIX[gateId]
    : Object.hasOwn(GATE_ENVIRONMENT_EVIDENCE_MATRIX, gateId)
      ? GATE_ENVIRONMENT_EVIDENCE_MATRIX[gateId]
      : null
  if (!matrix) throw new Error('phase10_unknown_gate')

  for (const relativePath of [
    ...(matrix.results ?? []),
    ...(gateId === 'coverage' ? coverageSubresults : [])
  ]) {
    // Do not recursively delete an unexpected directory. A cleanup error must
    // prevent the producer from running against evidence from an earlier run.
    fs.rmSync(path.join(root, relativePath), { force: true })
  }
}
